/* Activity evidence stays in this browser, alongside device-local progress. */
window.activityEvidence=(()=>{
 let dbPromise;
 function db(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open('ultra-of-us-evidence',1);request.onupgradeneeded=()=>request.result.createObjectStore('activities',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>{dbPromise=null;reject(Error('This browser could not save your activity. Please allow website storage and try again.'))};request.onblocked=()=>reject(Error('Please close other tabs of this site and try again.'))});return dbPromise}
 async function save(record){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('activities','readwrite');tx.objectStore('activities').put(record);tx.oncomplete=resolve;tx.onerror=()=>reject(Error('Your activity could not be saved. Please free some browser storage and try again.'));tx.onabort=()=>reject(Error('Your activity could not be saved. Please try again.'))})}
 async function get(id){const database=await db();return new Promise((resolve,reject)=>{const req=database.transaction('activities').objectStore('activities').get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
 function validateLink(value){let url;try{url=new URL(value.trim())}catch{throw Error('Paste a full Strava activity link starting with https://.')}if(url.protocol!=='https:'||url.username||url.password||url.port)throw Error('Use a secure Strava activity link.');const valid=(['strava.com','www.strava.com'].includes(url.hostname)&&/^\/activities\/\d+\/?$/.test(url.pathname))||(url.hostname==='strava.app.link'&&/^\/[a-zA-Z0-9_-]+\/?$/.test(url.pathname));if(!valid)throw Error('Use a Strava activity link, such as https://www.strava.com/activities/123456789, or a strava.app.link share link.');return url.href}
 async function photo(file){if(!file)throw Error('Choose a photo of your activity first.');if(file.size>20*1024*1024)throw Error('Choose a photo smaller than 20 MB.');if(!file.type.startsWith('image/')||file.type==='image/svg+xml')throw Error('Choose a photo in JPEG, PNG, WebP or another supported image format.');const src=URL.createObjectURL(file);try{const img=new Image();img.src=src;await img.decode();if(!img.naturalWidth||!img.naturalHeight)throw Error('Invalid image');const scale=Math.min(1,1600/Math.max(img.naturalWidth,img.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.round(img.naturalWidth*scale);canvas.height=Math.round(img.naturalHeight*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.85));if(!blob)throw Error('Image conversion failed');return blob}catch{throw Error('This photo could not be opened. Please choose a JPEG, PNG or WebP version.')}finally{URL.revokeObjectURL(src)}}
 async function remove(id){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('activities','readwrite');tx.objectStore('activities').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
 return{save,get,remove,validateLink,photo};
})();
